// js/class-page.js — behaviour for weekly-class listing pages
// (/classes/{county}/{slug}), generated by sortd-admin's generate-listings.js.
// The page embeds its own data as JSON in <script id="lp-data">.
//
// Main call to action: "Add to my Sortd calendar".
//  - Logged out: the button is greyed with a padlock; tapping it asks for an
//    email and sends the usual login link (creates the account). After
//    logging in, /account sends them back here with the sheet open.
//  - Logged in: pick the class slot (from the timetable), which child(ren),
//    and when it starts; it's saved to their Sortd calendar (the planner,
//    /planner) via /.netlify/functions/planner action "addClass". Google /
//    Apple / Outlook export is offered afterwards as a secondary option.
// Also: Save (heart), Share, the "Booked a place?" prompt after a Book
// click, and the mobile sticky action bar.
//
// Term dates and scheduling live in js/school-year.js (loaded on demand).
(function () {
  'use strict';
  var dataEl = document.getElementById('lp-data');
  if (!dataEl) return;
  var D; try { D = JSON.parse(dataEl.textContent); } catch (e) { return; }

  function whenReady(fn) {
    if (window.SortdSchoolYear) return fn();
    var s = document.createElement('script'); s.src = '/js/school-year.js'; s.onload = fn; document.head.appendChild(s);
  }
  whenReady(init);

  function init() {
  var SY = window.SortdSchoolYear;
  var API = '/.netlify/functions/planner';
  var DAY_NAMES = SY.DAY_NAMES, fmtTime = SY.fmtTime, nice = SY.nice, iso = SY.iso, parseISO = SY.parseISO, today = SY.today;
  var KID_COLOURS = { '--gr': '#1D8A52', '--pk': '#D45F86', '--sk': '#3D77A3', '--pu': '#5B4FCA', '--ochre': '#A6812F', '--teal': '#2F8584' };

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function track(name, extra) { try { if (window.gtag) window.gtag('event', name, Object.assign({ listing_id: D.id, listing_name: D.name, provider_name: D.provider, listing_type: 'class' }, extra || {})); } catch (_) {} }
  function loggedIn() { return document.cookie.split('; ').some(function (c) { return c === 'sortd_logged_in=1'; }); }

  var SESSIONS = SY.parseTimetable(D.times);
  var RUN_DAYS = []; String(D.days || '').split(/[,\n/&]+|\band\b/).forEach(function (w) { var i = SY.dayIndex(w.trim()); if (i !== -1 && RUN_DAYS.indexOf(i) === -1) RUN_DAYS.push(i); });
  var SINGLE = SY.parseRange(String(D.times || '').split('\n')[0].replace(/^[A-Za-z]+\.?\s*:?\s*/, ''));

  var layer = document.createElement('div'); document.body.appendChild(layer);
  var sel = { i: null, day: null, start: null, end: null, from: null, year: false, kids: [], newKids: [] };
  var myKids = null; // from the planner, once loaded
  var stage = 'pick'; // 'pick' → 'done'
  function close() { layer.innerHTML = ''; document.body.style.overflow = ''; }
  function sheet(inner) {
    layer.innerHTML = '<div class="cp-scrim" data-cp="close"><div class="cp-sheet" role="dialog" aria-modal="true" aria-labelledby="cp-t">' + inner + '</div></div>';
    document.body.style.overflow = 'hidden';
  }
  function head(title, sub) { return '<div class="cp-head"><div><h2 id="cp-t">' + title + '</h2>' + (sub ? '<p>' + sub + '</p>' : '') + '</div><button class="cp-x" data-cp="close" aria-label="Close">✕</button></div>'; }

  function chosen() {
    if (sel.i != null && SESSIONS[sel.i]) return SESSIONS[sel.i];
    if (sel.day != null && sel.start != null && sel.end > sel.start) return { day: sel.day, start: sel.start, end: sel.end, venue: '', label: '' };
    return null;
  }
  function earliest() { var t = today(), st = D.dateStart ? parseISO(D.dateStart) : null; return st && st > t ? st : t; }
  function limit() { var last = SY.lastTermDay(), end = D.dateEnd ? parseISO(D.dateEnd) : null; return end && end < last ? end : last; }
  function fromDate() { return sel.from ? parseISO(sel.from) : earliest(); }
  function untilDate(s) {
    var first = SY.firstOnOrAfter(fromDate(), s.day);
    var u = sel.year ? limit() : SY.currentTermEnd(first);
    return u > limit() ? limit() : u;
  }
  function plan(s) { return SY.runs(s.day, fromDate(), untilDate(s)); }
  function ev(s) {
    return { uid: D.id + '-' + s.day + '-' + s.start, title: D.name + (s.label ? ' (' + s.label + ')' : ''), day: s.day, start: s.start, end: s.end, url: D.url,
      location: s.venue ? s.venue + ', ' + D.area : (D.location || D.area),
      details: [D.provider, s.venue ? 'Venue: ' + s.venue : '', D.cost ? 'Cost: ' + D.cost : '', D.bookingUrl ? 'Book or check dates: ' + D.bookingUrl : '', 'On Sortd: ' + D.url,
        'Weekly in term time. Skips midterm and bank holidays. Check term dates with the provider.'].filter(Boolean).join('\n') };
  }
  function minsToInput(m) { return pad(Math.floor(m / 60)) + ':' + pad(m % 60); }
  function inputToMins(v) { var p = String(v || '').split(':'); return p.length === 2 ? (+p[0]) * 60 + (+p[1]) : null; }

  function sessionList() {
    var groups = [], key = null;
    SESSIONS.forEach(function (s, i) { var k = s.day + '|' + s.venue; if (k !== key) { groups.push({ day: s.day, venue: s.venue, items: [] }); key = k; } groups[groups.length - 1].items.push(i); });
    return '<fieldset class="cp-fs"><legend>Which class?</legend>' + groups.map(function (g) {
      return '<div class="cp-grp"><div class="cp-grp-h">' + DAY_NAMES[g.day] + (g.venue ? ' · ' + esc(g.venue) : '') + '</div>' + g.items.map(function (i) {
        var s = SESSIONS[i];
        return '<label class="cp-opt"><input type="radio" name="cp-s" value="' + i + '"' + (sel.i === i ? ' checked' : '') + '><span><b>' + fmtTime(s.start) + '–' + fmtTime(s.end) + '</b>' + (s.label ? ' ' + esc(s.label) : '') + '</span></label>';
      }).join('') + '</div>';
    }).join('') + '</fieldset>';
  }
  function manual() {
    var days = RUN_DAYS.length ? RUN_DAYS : [1, 2, 3, 4, 5, 6, 0];
    if (sel.day == null) sel.day = days[0];
    if (sel.start == null && SINGLE) { sel.start = SINGLE.start; sel.end = SINGLE.end; }
    return '<div class="cp-row"><label class="cp-f">Day<select id="cp-day">' + days.map(function (d) { return '<option value="' + d + '"' + (sel.day === d ? ' selected' : '') + '>' + DAY_NAMES[d] + '</option>'; }).join('') + '</select></label>' +
      '<label class="cp-f">Starts<input type="time" id="cp-start" value="' + (sel.start != null ? minsToInput(sel.start) : '') + '"></label>' +
      '<label class="cp-f">Ends<input type="time" id="cp-end" value="' + (sel.end != null ? minsToInput(sel.end) : '') + '"></label></div>' +
      (D.times ? '<p class="cp-hint">The provider lists: ' + esc(D.times.split('\n')[0]) + '</p>' : '');
  }
  function kidsPicker() {
    if (myKids === null) return '<div class="cp-f"><span>Who\'s going?</span><p class="cp-hint">Loading your children…</p></div>';
    var chips = myKids.map(function (k) {
      var on = sel.kids.indexOf(k.id) !== -1;
      return '<button type="button" class="cp-kid' + (on ? ' on' : '') + '" data-kid="' + esc(k.id) + '" aria-pressed="' + on + '"><i style="background:' + (KID_COLOURS[k.col] || '#5B4FCA') + '"></i>' + esc(k.name) + '</button>';
    }).join('');
    var news = sel.newKids.map(function (k, i) {
      return '<div class="cp-row cp-newkid"><label class="cp-f">Child\'s first name<input class="nk-name" data-i="' + i + '" value="' + esc(k.name) + '" maxlength="30"></label>' +
        '<label class="cp-f cp-f--age">Age<input class="nk-age" data-i="' + i + '" type="number" min="0" max="17" inputmode="numeric" value="' + esc(k.age) + '"></label></div>';
    }).join('');
    return '<div class="cp-f"><span>Who\'s going?</span>' + (chips ? '<div class="cp-kids">' + chips + '</div>' : '') + news +
      '<button type="button" class="cp-link" data-cp="addkid">+ Add ' + (myKids.length || sel.newKids.length ? 'another' : 'a') + ' child</button></div>';
  }
  function kidsChosen() { return sel.kids.length + sel.newKids.filter(function (k) { return k.name.trim(); }).length; }
  function summary() {
    var s = chosen(); if (!s) return '<p class="cp-hint">' + (SESSIONS.length ? 'Pick a class above.' : 'Add the day and time your child goes.') + '</p>';
    var rs = plan(s); if (!rs.length) return '<p class="cp-hint">No more term-time ' + DAY_NAMES[s.day] + 's this school year.</p>';
    var n = rs.reduce(function (a, r) { return a + SY.count(r); }, 0), last = rs[rs.length - 1].last;
    return '<div class="cp-sum"><b>' + DAY_NAMES[s.day] + 's ' + fmtTime(s.start) + '–' + fmtTime(s.end) + '</b>, ' + nice(rs[0].first) + ' to ' + nice(last) + ' · ' + n + ' class' + (n === 1 ? '' : 'es') +
      '<br><span>Skips midterm, school holidays and bank holidays.</span></div>' +
      '<div class="cp-acts"><button class="cp-btn cp-btn--pri" id="cp-add" type="button"' + (kidsChosen() ? '' : ' disabled') + '>Add to my Sortd calendar</button>' +
      (kidsChosen() ? '' : '<p class="cp-hint">Choose who\'s going.</p>') + '</div>';
  }
  function renderPick() {
    var startVal = sel.from || iso(earliest());
    sheet(head('Add to my Sortd calendar', esc(D.name)) +
      '<div id="cp-kidsbox">' + kidsPicker() + '</div>' +
      (SESSIONS.length ? sessionList() : manual()) +
      '<div class="cp-row"><label class="cp-f">First class on or after<input type="date" id="cp-from" value="' + startVal + '" min="' + iso(today()) + '"></label>' +
      '<label class="cp-chk"><input type="checkbox" id="cp-year"' + (sel.year ? ' checked' : '') + '> Carry on after this term (to ' + nice(limit()) + ')</label></div>' +
      '<div id="cp-sum">' + summary() + '</div>');
  }
  function renderDone(names) {
    var s = chosen(), rs = plan(s), e = ev(s);
    sheet(head('Added to your Sortd calendar', '') +
      '<div class="cp-sum"><b>' + esc(D.name) + '</b><br>' + DAY_NAMES[s.day] + 's ' + fmtTime(s.start) + '–' + fmtTime(s.end) + ' for ' + esc(names) +
      '<br><span>' + nice(rs[0].first) + ' to ' + nice(rs[rs.length - 1].last) + '. Skips midterm, holidays and bank holidays.</span></div>' +
      '<div class="cp-acts"><a class="cp-btn cp-btn--pri" href="/planner#calendar">Open my Sortd calendar</a></div>' +
      '<details class="cp-more"><summary>Also add it to my phone\'s calendar</summary><div class="cp-acts">' +
      '<a class="cp-btn" id="cp-google" href="' + esc(SY.googleLink(e, rs[0])) + '" target="_blank" rel="noopener noreferrer">Google Calendar' + (rs.length > 1 ? ' (this term)' : '') + '</a>' +
      '<button class="cp-btn" id="cp-ics" type="button">Apple, Outlook or other</button></div></details>');
  }
  function refresh() { var el = document.getElementById('cp-sum'); if (el) el.innerHTML = summary(); }
  function refreshKids() { var el = document.getElementById('cp-kidsbox'); if (el) el.innerHTML = kidsPicker(); refresh(); }

  function loadKids() {
    return fetch(API, { credentials: 'same-origin' }).then(function (r) { return r.json(); }).then(function (d) {
      myKids = (d.plan && Array.isArray(d.plan.kids)) ? d.plan.kids : [];
      if (myKids.length === 1 && !sel.kids.length) sel.kids = [myKids[0].id];
      if (!myKids.length && !sel.newKids.length) sel.newKids.push({ name: '', age: '' });
    }).catch(function () { myKids = []; if (!sel.newKids.length) sel.newKids.push({ name: '', age: '' }); });
  }
  function open() {
    stage = 'pick'; renderPick(); track('add_to_calendar_open');
    if (myKids === null) loadKids().then(function () { if (stage === 'pick' && layer.innerHTML) refreshKids(); });
  }
  function submit() {
    var s = chosen(); if (!s) return;
    var btn = document.getElementById('cp-add'); if (btn) { btn.disabled = true; btn.textContent = 'Adding…'; }
    var newKids = sel.newKids.filter(function (k) { return k.name.trim(); });
    var rs = plan(s);
    var body = { action: 'addClass', kidIds: sel.kids.slice(), newKids: newKids,
      cls: { day: s.day, start: s.start, end: s.end, venue: s.venue || '', label: s.label || '', from: iso(rs[0].first), until: iso(rs[rs.length - 1].last),
        listing: { id: D.id, name: D.name, provider: D.provider, url: D.url, area: D.area, bookingUrl: D.bookingUrl } } };
    fetch(API, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw new Error(j.error || 'error'); return j; }); })
      .then(function (j) {
        myKids = j.kids || myKids;
        var names = (myKids || []).filter(function (k) { return sel.kids.indexOf(k.id) !== -1; }).map(function (k) { return k.name; }).concat(newKids.map(function (k) { return k.name.trim(); }));
        sel.kids = []; sel.newKids = [];
        stage = 'done'; renderDone(names.join(' and ') || 'your child');
        track('add_to_sortd_calendar');
      })
      .catch(function (err) {
        if (btn) { btn.disabled = false; btn.textContent = 'Add to my Sortd calendar'; }
        var el = document.getElementById('cp-sum');
        if (el) el.insertAdjacentHTML('beforeend', '<p class="cp-hint cp-err">' + (err.message === 'not_logged_in' ? 'You\'ve been logged out. Refresh the page and log in again.' : 'Couldn\'t add it just now. Please try again.') + '</p>');
      });
  }

  function signupSheet() {
    sheet(head('Add classes to your Sortd calendar', 'Free with a Sortd account. Pop in your email and we\'ll send you a link to log in. No password needed.') +
      '<form id="cp-signup" class="cp-acts" novalidate><label class="cp-f">Your email<input type="email" id="cp-email" autocomplete="email" required placeholder="you@example.ie"></label>' +
      '<button class="cp-btn cp-btn--pri" type="submit">Create my free account</button>' +
      '<label class="cp-opt" style="display:flex;gap:8px;align-items:flex-start;margin:10px 0 0;font-size:13px;line-height:1.45;text-align:left;font-weight:600;flex:1 1 100%;"><input type="checkbox" id="cp-optin" style="margin-top:2px;flex:0 0 auto;width:16px;height:16px;"> <span>Also send me the weekly "what\'s on near you" email every Thursday: new camps, open spots and honest updates. See our <a href="/privacy-policy" target="_blank" rel="noopener">Privacy Policy</a>.</span></label>' +
      '</form>' +
      '<p class="cp-hint" id="cp-msg" role="status" aria-live="polite">Already have an account? Same thing: enter your email and we\'ll send you a login link.</p>');
    var f = document.getElementById('cp-email'); if (f) f.focus();
    track('calendar_locked_click');
  }

  layer.addEventListener('submit', function (e) {
    if (e.target.id !== 'cp-signup') return;
    e.preventDefault();
    var input = document.getElementById('cp-email'), msg = document.getElementById('cp-msg'), btn = e.target.querySelector('button');
    var email = input.value.trim();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { msg.textContent = 'Please enter a valid email address.'; input.focus(); return; }
    btn.disabled = true; btn.textContent = 'Sending…';
    try { localStorage.setItem('sortd_return_to', location.pathname + '#add-to-calendar'); } catch (_) {}
    fetch('/.netlify/functions/request-login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: email, newsletterOptIn: !!(document.getElementById('cp-optin') && document.getElementById('cp-optin').checked) }) })
      .then(function (r) { return r.json().then(function (j) { if (!r.ok) throw new Error(j.error || 'error'); return j; }); })
      .then(function () {
        e.target.outerHTML = '<div class="cp-sum"><b>Check your inbox</b><br><span>We\'ve sent a login link to ' + esc(email) + '. Open it on this phone or computer and you\'ll come straight back to this class, ready to add it to your Sortd calendar.</span></div>';
        msg.textContent = 'The link works once and expires after 30 minutes.';
        track('calendar_signup_requested');
      })
      .catch(function (err) { btn.disabled = false; btn.textContent = 'Create my free account'; msg.textContent = (err && err.message && err.message !== 'error') ? err.message : 'Something went wrong. Please try again.'; });
  });
  layer.addEventListener('click', function (e) {
    var c = e.target.closest('[data-cp="close"]');
    if (c && (e.target === c || c.classList.contains('cp-x'))) { close(); return; }
    var kid = e.target.closest('.cp-kid');
    if (kid) { var id = kid.getAttribute('data-kid'), i = sel.kids.indexOf(id); if (i === -1) sel.kids.push(id); else sel.kids.splice(i, 1); refreshKids(); return; }
    if (e.target.closest('[data-cp="addkid"]')) { sel.newKids.push({ name: '', age: '' }); refreshKids(); var ins = layer.querySelectorAll('.nk-name'); if (ins.length) ins[ins.length - 1].focus(); return; }
    if (e.target.id === 'cp-add') { submit(); return; }
    if (e.target.id === 'cp-ics') { var s = chosen(); if (s) { SY.download((D.slug || 'sortd-class') + '.ics', SY.ics([[ev(s), plan(s)]])); track('add_to_calendar', { method: 'ics' }); } }
    if (e.target.id === 'cp-google') track('add_to_calendar', { method: 'google' });
  });
  layer.addEventListener('input', function (e) {
    var t = e.target, i = +t.getAttribute('data-i');
    if (t.classList.contains('nk-name')) { sel.newKids[i].name = t.value; refresh(); }
    if (t.classList.contains('nk-age')) { sel.newKids[i].age = t.value; }
  });
  layer.addEventListener('change', function (e) {
    var t = e.target;
    if (t.name === 'cp-s') sel.i = +t.value;
    else if (t.id === 'cp-day') sel.day = +t.value;
    else if (t.id === 'cp-start') sel.start = inputToMins(t.value);
    else if (t.id === 'cp-end') sel.end = inputToMins(t.value);
    else if (t.id === 'cp-from') sel.from = t.value || null;
    else if (t.id === 'cp-year') sel.year = t.checked;
    else return;
    refresh();
  });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && layer.innerHTML) close(); });

  // ---- Buttons on the page ----
  var LOCKED = !loggedIn();
  document.querySelectorAll('[data-lp="calendar"]').forEach(function (b) {
    // Label (older generated pages say "Add to my calendar")
    var txt = Array.prototype.find.call(b.childNodes, function (n) { return n.nodeType === 3 && n.textContent.trim(); });
    if (txt) txt.textContent = ' Add to my Sortd calendar';
    if (b.hasAttribute('aria-label')) b.setAttribute('aria-label', 'Add to my Sortd calendar');
    if (LOCKED) { b.classList.add('is-locked'); var ic = b.querySelector('.ti'); if (ic) ic.className = 'ti ti-lock'; b.setAttribute('title', 'Free account needed'); }
    b.addEventListener('click', function () { if (loggedIn()) open(); else signupSheet(); });
  });
  if (!LOCKED && location.hash === '#add-to-calendar') { history.replaceState(null, '', location.pathname); setTimeout(open, 300); }

  document.querySelectorAll('[data-lp="share"]').forEach(function (b) {
    b.addEventListener('click', function () {
      var text = 'Found this on Sortd: ' + D.name; track('share_click');
      if (navigator.share) { navigator.share({ title: D.name, text: text, url: D.url }).catch(function () {}); return; }
      window.open('https://wa.me/?text=' + encodeURIComponent(text + ' ' + D.url), '_blank', 'noopener');
    });
  });
  document.querySelectorAll('[data-save-id]').forEach(function (b) {
    b.addEventListener('click', function () { if (window.SortdSaved) window.SortdSaved.toggle(b.getAttribute('data-save-id'), b); });
  });

  // After a booking click, nudge them to add it to their Sortd calendar.
  var KEY = 'sortd_book_click_' + D.id;
  function showBookedPrompt() { var box = document.getElementById('lp-booked'); if (box) box.hidden = false; }
  document.querySelectorAll('[data-track="booking"]').forEach(function (a) {
    a.addEventListener('click', function () { try { localStorage.setItem(KEY, String(Date.now())); } catch (_) {} setTimeout(showBookedPrompt, 800); });
  });
  try { var t = +localStorage.getItem(KEY); if (t && Date.now() - t < 60 * 864e5) showBookedPrompt(); } catch (_) {}
  var booked = document.getElementById('lp-booked');
  if (booked) { var bt = booked.childNodes[1]; if (bt && bt.nodeType === 3) bt.textContent = 'Add it to your Sortd calendar so you don\'t miss a week.'; }
  var dismiss = document.getElementById('lp-booked-x');
  if (dismiss) dismiss.addEventListener('click', function () { try { localStorage.removeItem(KEY); } catch (_) {} document.getElementById('lp-booked').hidden = true; });

  // Mobile: sticky action bar once the main action card scrolls away.
  var card = document.querySelector('.lp-act'), bar = document.querySelector('.lp-bar');
  if (card && bar && 'IntersectionObserver' in window) {
    new IntersectionObserver(function (ents) { bar.classList.toggle('show', !ents[0].isIntersecting); }, { threshold: 0 }).observe(card);
  }
  window.SortdClassPage = { open: open };
  }
})();
